/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import jakarta.transaction.Transactional;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlertChangeSet;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlertStatusOptions;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertFilter;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleReference;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.store.Levels;
import net.civeira.phylax.feature.observe.store.ObsLog;

/**
 * Evaluates the alert rules and records their alerts in observed-alert: at most one open (FIRING)
 * alert per rule and problem key; it is resolved when the condition ends.
 *
 * <ul>
 * <li>new-issue / regression: with the changes of each batch of the writer.</li>
 * <li>error-rate, source-silent, collector-dropping, disk-high: every minute ({@link #tick}).</li>
 * </ul>
 * The alert is stored in a short transaction and the notice is delivered after it, outside it: a
 * slow webhook never holds a connection. A notice that fails, or that a muted rule holds, stays
 * pending (last-notified-at empty) and the minute scheduler retries it. Two notices of the same
 * rule and problem are separated at least by its cooldown.
 */
@ApplicationScoped
@Slf4j
public class AlertEngine {

  private static final String OWN_PACKAGE = "net.civeira.phylax.feature.observe";
  private static final String COLLECTOR_KEY = "collector";
  private static final String DISK_KEY = "disk";
  /** Percentage of max-disk-mb of a disk-high rule without threshold. */
  private static final int DISK_HIGH_DEFAULT = 80;

  private final AlertRules rules;
  private final AlertDispatcher dispatcher;
  private final ObservedAlertCommandRepositoryGateway alerts;
  private final SourceRegistry registry;
  private final net.civeira.phylax.feature.observe.slo.SloEvaluator slos;
  private final net.civeira.phylax.feature.observe.probe.ProbeRunner probes;
  private final net.civeira.phylax.feature.observe.anomaly.ObserveInsights insights;
  private final Event<ObserveAlertEvent> events;
  private final String publicUrl;
  private final ErrorRateWindow errors = new ErrorRateWindow();
  private final Map<String, Instant> lastNotified = new ConcurrentHashMap<>();
  private volatile long lastDropped = -1;

  public AlertEngine(final AlertRules rules, final AlertDispatcher dispatcher,
      final ObservedAlertCommandRepositoryGateway alerts, final SourceRegistry registry,
      final net.civeira.phylax.feature.observe.slo.SloEvaluator slos,
      final net.civeira.phylax.feature.observe.probe.ProbeRunner probes,
      final net.civeira.phylax.feature.observe.anomaly.ObserveInsights insights,
      final Event<ObserveAlertEvent> events,
      final @ConfigProperty(name = "app.observe.public-url") Optional<String> publicUrl) {
    this.rules = rules;
    this.dispatcher = dispatcher;
    this.alerts = alerts;
    this.registry = registry;
    this.slos = slos;
    this.probes = probes;
    this.insights = insights;
    this.events = events;
    this.publicUrl = publicUrl.map(url -> url.replaceAll("/+$", "")).orElse("");
  }

  /** Batch of the writer: counts the errors and evaluates the issue rules. */
  public void onBatch(final List<ObsLog> logs, final List<IssueChange> changes) {
    for (ObsLog log : logs) {
      if (Levels.atLeast(log.level(), "ERROR")
          && (null == log.logger() || !log.logger().startsWith(OWN_PACKAGE))) {
        errors.add(log.src(), log.ts());
      }
    }
    for (IssueChange change : changes) {
      String trigger = change.regression() ? "regression" : "new-issue";
      for (AlertRules.Rule rule : rules.of(trigger)) {
        if (rule.watches(change.originUid()) && levelOk(rule, change.level())) {
          Map<String, Object> details = new LinkedHashMap<>();
          details.put("origin", Map.of("code", String.valueOf(change.originCode())));
          details.put("issue", issueDetails(change));
          fire(rule, change.issueUid(),
              (change.regression() ? "Regression: " : "New issue: ") + change.title(),
              "#/issues/" + change.issueUid(), details);
        }
      }
    }
  }

  /** Every minute: rules that depend on time, and the pending notices. */
  public void tick(final long droppedTotal) {
    tick(droppedTotal, 0);
  }

  /**
   * @param droppedTotal events lost since the start
   * @param diskRatio used fraction of max-disk-mb (0 without limit)
   */
  public void tick(final long droppedTotal, final double diskRatio) {
    long now = System.currentTimeMillis();
    for (AlertRules.Rule rule : rules.of("disk-high")) {
      int percent = rule.threshold() > 0 ? rule.threshold() : DISK_HIGH_DEFAULT;
      long used = Math.round(diskRatio * 100);
      if (used >= percent) {
        fire(rule, DISK_KEY,
            "The observability store uses " + used + " % of its disk limit (threshold " + percent
                + " %)",
            "#/sources", Map.of("metric", Map.of("value", used, "threshold", percent)));
      } else {
        resolve(rule, DISK_KEY);
      }
    }
    for (AlertRules.Rule rule : rules.of("error-rate")) {
      String code = codeOf(rule.originUid());
      double rate = errors.perMinute(code, rule.windowMinutes(), now);
      String key = null == rule.originUid() ? "all" : rule.originUid();
      if (rate >= rule.threshold()) {
        Map<String, Object> details = new LinkedHashMap<>();
        details.put("metric", Map.of("value", Math.round(rate * 10) / 10.0, "threshold",
            rule.threshold(), "window", rule.windowMinutes()));
        details.put("origin", Map.of("code", null == code ? "all" : code));
        fire(rule, key,
            String.format("%.1f errors/min in %s (threshold %d, last %d min)", rate,
                null == code ? "all the sources" : code, rule.threshold(), rule.windowMinutes()),
            "#/logs", details);
      } else {
        resolve(rule, key);
      }
    }
    for (AlertRules.Rule rule : rules.of("source-silent")) {
      for (SourceRegistry.Source source : registry.all()) {
        if (!source.accepting() || !rule.watches(source.uid())) {
          continue;
        }
        Optional<Long> seen = registry.lastSeen(source.code());
        if (seen.isEmpty()) {
          continue; // Never seen since the start: nothing to compare with
        }
        long silent = (now - seen.get()) / 60_000;
        int expected = source.expectedEveryMinutes() > 0 ? source.expectedEveryMinutes()
            : rule.windowMinutes();
        if (silent >= expected) {
          fire(rule, source.uid(), source.code() + " has sent nothing for " + silent + " min",
              "#/sources", Map.of("origin", Map.of("code", source.code())));
        } else {
          resolve(rule, source.uid());
        }
      }
    }
    long dropped = droppedTotal - (lastDropped < 0 ? droppedTotal : lastDropped);
    lastDropped = droppedTotal;
    for (AlertRules.Rule rule : rules.of("collector-dropping")) {
      if (dropped > 0) {
        fire(rule, COLLECTOR_KEY, "The collector dropped " + dropped + " events in the last minute",
            "#/sources", Map.of("metric", Map.of("value", dropped)));
      } else {
        resolve(rule, COLLECTOR_KEY);
      }
    }
    for (AlertRules.Rule rule : rules.of("slo-burn")) {
      for (var slo : slos.current()) {
        if (!rule.watches(slo.originUid())) {
          continue;
        }
        if (slo.fastBurn() || slo.slowBurn()) {
          double burn = slo.fastBurn() ? slo.burn1h() : slo.burn6h();
          fire(rule, slo.uid(),
              String.format("Objective %s is burning its error budget %.1fx (%s window)",
                  slo.name(), burn, slo.fastBurn() ? "1 h" : "6 h"),
              "#/slos",
              Map.of("origin", Map.of("code", slo.source()), "metric",
                  Map.of("value", Math.round(burn * 10) / 10.0, "threshold",
                      slo.fastBurn() ? 14.4 : 6, "window", slo.fastBurn() ? 60 : 360)));
        } else {
          resolve(rule, slo.uid());
        }
      }
    }
    for (var probe : probes.states()) {
      for (AlertRules.Rule rule : rules.of("probe-down")) {
        if (!rule.watches(probe.originUid())) {
          continue;
        }
        if (!probe.up() && probe.failures() >= probe.failuresToAlert()) {
          fire(rule, probe.uid(), "Probe " + probe.name() + " is down: " + probe.error(),
              "#/uptime", Map.of("origin", Map.of("code", probe.source())));
        } else if (probe.up()) {
          resolve(rule, probe.uid());
        }
      }
      for (AlertRules.Rule rule : rules.of("tls-expiring")) {
        if (!rule.watches(probe.originUid()) || null == probe.tlsExpiresAt()) {
          continue;
        }
        long days = (probe.tlsExpiresAt() - now) / 86_400_000L;
        if (days < probe.tlsWarnDays()) {
          fire(rule, "tls:" + probe.uid(),
              "The certificate of " + probe.url() + " expires in " + days + " days", "#/uptime",
              Map.of("origin", Map.of("code", probe.source())));
        } else {
          resolve(rule, "tls:" + probe.uid());
        }
      }
    }
    java.util.Set<String> anomalous = new java.util.HashSet<>();
    for (var anomaly : insights.anomalies()) {
      anomalous.add(anomaly.source() + "/" + anomaly.metric());
    }
    for (AlertRules.Rule rule : rules.of("anomaly")) {
      for (SourceRegistry.Source source : registry.all()) {
        if (!rule.watches(source.uid())) {
          continue;
        }
        for (String metric : List.of("rpm", "errorRate", "p95")) {
          String key = source.code() + "/" + metric;
          var anomaly = insights.anomalies().stream()
              .filter(a -> a.source().equals(source.code()) && a.metric().equals(metric))
              .findFirst();
          if (anomaly.isPresent()) {
            var a = anomaly.get();
            fire(rule, key,
                String.format("%s of %s is %s: %.1f (usual %.1f ± %.1f)", metric, source.code(),
                    "up".equals(a.direction()) ? "high" : "low", a.value(), a.mean(), a.std()),
                "#/insights", Map.of("origin", Map.of("code", source.code()), "metric",
                    Map.of("value", a.value(), "threshold", a.mean(), "window", 15)));
          } else if (!anomalous.contains(key)) {
            resolve(rule, key);
          }
        }
      }
    }
    retryPending();
  }

  private void fire(final AlertRules.Rule rule, final String key, final String summary,
      final String link, final Map<String, Object> details) {
    Optional<ObservedAlert> created = inRequest(() -> self().open(rule.uid(), key, summary, link));
    created.ifPresent(alert -> notify(rule, alert, "FIRING", details));
  }

  private void resolve(final AlertRules.Rule rule, final String key) {
    Optional<ObservedAlert> closed = inRequest(() -> self().close(rule.uid(), key));
    closed.ifPresent(alert -> {
      if (alert.getLastNotifiedAt().isPresent()) {
        notify(rule, alert, "RESOLVED", Map.of());
      } else {
        publish(alert, rule, "RESOLVED");
      }
    });
  }

  /** Creates the alert if the rule has none open for that key. */
  @Transactional
  public Optional<ObservedAlert> open(final String ruleUid, final String key, final String summary,
      final String link) {
    if (findOpen(ruleUid, key).isPresent()) {
      return Optional.empty();
    }
    ObservedAlertChangeSet change = new ObservedAlertChangeSet().newUid()
        .rule(ObservedAlertRuleReference.of(ruleUid)).problemKey(key)
        .summary(summary.length() > 250 ? summary.substring(0, 249) + "…" : summary).link(link)
        .firedAt(now());
    return Optional.of(alerts.create(ObservedAlert.create(change)));
  }

  /** Resolves the open alert of the rule and key, if any. */
  @Transactional
  public Optional<ObservedAlert> close(final String ruleUid, final String key) {
    return findOpen(ruleUid, key).map(open -> alerts.update(open, open.closeAlert(now())));
  }

  @Transactional
  public void markNotified(final String alertUid) {
    alerts.find(ObservedAlertFilter.builder().uid(alertUid).build())
        .ifPresent(alert -> alerts.update(alert, alert.markNotified(now())));
  }

  /** The open alerts whose notice is pending: retried every minute. */
  @Transactional
  public List<ObservedAlert> pending() {
    return alerts
        .list(ObservedAlertFilter.builder().status(ObservedAlertStatusOptions.FIRING).build())
        .stream().filter(alert -> alert.getLastNotifiedAt().isEmpty()).toList();
  }

  private void retryPending() {
    List<ObservedAlert> pending = inRequest(() -> self().pending());
    Map<String, AlertRules.Rule> byUid = new LinkedHashMap<>();
    rules.all().forEach(rule -> byUid.put(rule.uid(), rule));
    for (ObservedAlert alert : pending) {
      AlertRules.Rule rule = byUid.get(alert.getRuleUid());
      if (null != rule) {
        notify(rule, alert, "FIRING", Map.of());
      }
    }
  }

  private void notify(final AlertRules.Rule rule, final ObservedAlert alert, final String status,
      final Map<String, Object> details) {
    publish(alert, rule, status);
    Instant now = Instant.now();
    String cooldownKey = rule.uid() + "\n" + alert.getProblemKey() + "\n" + status;
    Instant previous = lastNotified.get(cooldownKey);
    boolean cooling =
        null != previous && now.isBefore(previous.plusSeconds(60L * rule.cooldownMinutes()));
    if (rule.muted(now) || cooling || !dispatcher.available(rule.channel())) {
      return;
    }
    AlertNotification notification = new AlertNotification(alert.getUid(), rule.uid(), rule.name(),
        rule.trigger(), status, rule.channel(), rule.target(), alert.getSummary(),
        publicUrl + "/observe/" + alert.getLink().orElse(""), details);
    try {
      dispatcher.deliver(notification);
      lastNotified.put(cooldownKey, now);
      if ("FIRING".equals(status)) {
        inRequest(() -> {
          self().markNotified(alert.getUid());
          return null;
        });
      }
    } catch (RuntimeException ex) {
      // WARN without stack trace: the logs of this package never become issues nor alerts
      log.warn("Unable to notify the alert {} of the rule {} by {}: {}", alert.getUid(),
          rule.name(), rule.channel(), ex.getMessage());
    }
  }

  private void publish(final ObservedAlert alert, final AlertRules.Rule rule, final String status) {
    try {
      events.fire(new ObserveAlertEvent(alert.getUid(), rule.uid(), rule.trigger(), status,
          alert.getProblemKey(), alert.getSummary(), alert.getLink().orElse(null)));
    } catch (RuntimeException ex) {
      log.warn("An observer of the alert {} failed: {}", alert.getUid(), ex.getMessage());
    }
  }

  private Optional<ObservedAlert> findOpen(final String ruleUid, final String key) {
    return alerts
        .list(ObservedAlertFilter.builder().rule(ObservedAlertRuleReference.of(ruleUid))
            .problemKey(key).status(ObservedAlertStatusOptions.FIRING).build())
        .stream().findFirst();
  }

  private String codeOf(final String originUid) {
    if (null == originUid) {
      return null;
    }
    return registry.all().stream().filter(source -> originUid.equals(source.uid()))
        .map(SourceRegistry.Source::code).findFirst().orElse(originUid);
  }

  private static boolean levelOk(final AlertRules.Rule rule, final String level) {
    return !"fatal".equals(rule.minLevel()) || "FATAL".equalsIgnoreCase(level);
  }

  private static Map<String, Object> issueDetails(final IssueChange change) {
    Map<String, Object> issue = new LinkedHashMap<>();
    issue.put("uid", change.issueUid());
    issue.put("title", change.title());
    issue.put("count", change.count());
    issue.put("users", change.users());
    issue.put("release", null == change.release() ? "" : change.release());
    return issue;
  }

  private static OffsetDateTime now() {
    return OffsetDateTime.now(ZoneOffset.UTC);
  }

  private AlertEngine self() {
    // Through the container, so @Transactional applies (a call to this would skip it)
    return Arc.container().instance(AlertEngine.class).get();
  }

  /** The writer and the scheduler threads have no request context: some adapters need one. */
  private static <T> T inRequest(final Supplier<T> work) {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      return work.get();
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }

  /** For the tests and the viewer: the current errors per minute of a source. */
  public double errorRate(final String sourceCode, final int windowMinutes) {
    return errors.perMinute(sourceCode, windowMinutes, System.currentTimeMillis());
  }
}
